// Simple Asteroid Dodge game
// Canvas element with id="game" must exist in the HTML.
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return console.error('Canvas #game not found');
  const ctx = canvas.getContext('2d');
  const width = (canvas.width = canvas.clientWidth || 400);
  const height = (canvas.height = canvas.clientHeight || 600);

  // Ship definition
  const ship = { w: 40, h: 20, x: width / 2, y: height - 30, speed: 6 };
  const keys = { left: false, right: false };

  // Asteroids
  const asteroids = [];
  let lastSpawn = 0;
  let spawnInterval = 1000; // ms
  let speedInc = 0.02; // increase per second
  let score = 0;
  let gameOver = false;

  // Input handling
  document.addEventListener('keydown', e => {
    if (e.key === 'ArrowLeft') keys.left = true;
    if (e.key === 'ArrowRight') keys.right = true;
  });
  document.addEventListener('keyup', e => {
    if (e.key === 'ArrowLeft') keys.left = false;
    if (e.key === 'ArrowRight') keys.right = false;
  });

  function spawnAsteroid() {
    const radius = Math.random() * 15 + 10;
    const x = Math.random() * (width - radius * 2) + radius;
    const speed = 2 + Math.random() * 2 + (score / 1000);
    asteroids.push({ x, y: -radius, r: radius, s: speed });
  }

  function update(dt) {
    // ship movement
    if (keys.left) ship.x -= ship.speed;
    if (keys.right) ship.x += ship.speed;
    ship.x = Math.max(ship.w / 2, Math.min(width - ship.w / 2, ship.x));

    // spawn asteroids
    if (Date.now() - lastSpawn > spawnInterval) {
      spawnAsteroid();
      lastSpawn = Date.now();
      // gradually increase difficulty
      spawnInterval = Math.max(200, spawnInterval - 10);
    }

    // update asteroids
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.y += a.s;
      // collision detection (simple rectangle-circle)
      const dx = Math.abs(a.x - ship.x);
      const dy = Math.abs(a.y - ship.y);
      if (dx < ship.w / 2 + a.r && dy < ship.h / 2 + a.r) {
        gameOver = true;
      }
      // remove off‑screen
      if (a.y - a.r > height) asteroids.splice(i, 1);
    }
    score += dt;
  }

  function draw() {
    ctx.clearRect(0, 0, width, height);
    // ship
    ctx.fillStyle = '#0af';
    ctx.fillRect(ship.x - ship.w / 2, ship.y - ship.h / 2, ship.w, ship.h);
    // asteroids
    ctx.fillStyle = '#a44';
    asteroids.forEach(a => {
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.r, 0, Math.PI * 2);
      ctx.fill();
    });
    // score
    ctx.fillStyle = '#000';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + Math.floor(score / 1000), 10, 20);
    // game over
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0, 0, width, height);
      ctx.fillStyle = '#fff';
      ctx.textAlign = 'center';
      ctx.font = '32px sans-serif';
      ctx.fillText('Game Over', width / 2, height / 2);
    }
  }

  let lastTime = performance.now();
  function loop(now) {
    const dt = now - lastTime;
    lastTime = now;
    if (!gameOver) update(dt);
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);
})();
